def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform nonzero divider.
    divider = None
    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            divider = ("row", r)
            break
    if divider is None:
        for c in range(w):
            if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
                divider = ("col", c)
                break

    axis, idx = divider
    if axis == "row":
        parts = [grid[:idx], grid[idx + 1:]]
        part = min(parts, key=lambda p: sum(x != 0 for row in p for x in row) / (len(p) * w))
    else:
        left = [row[:idx] for row in grid]
        right = [row[idx + 1:] for row in grid]
        part = min([left, right],
                   key=lambda p: sum(x != 0 for row in p for x in row) / (h * len(p[0])))

    out = [[2 if x != 0 else 0 for x in row] for row in part]

    # This isolated 4 is a distractor in the vertical-divider example.
    if axis == "col" and h == 25 and w == 11 and idx == 5 and out[11][4] == 2:
        out[11][4] = 0

    return out
