    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1

    stripes = []
    for r, row in enumerate(grid):
        if row[0] != 0 and all(value == row[0] for value in row):
            stripes.append((counts[row[0]], "row", r))
    for c in range(w):
        value = grid[0][c]
        if value != 0 and all(grid[r][c] == value for r in range(h)):
            stripes.append((counts[value], "col", c))

    _, axis, i = min(stripes)
    if axis == "row":
        top, bottom = grid[:i], grid[i + 1:]
        n = min(len(top), len(bottom))
        return [[2 if top[r][c] != 0 and bottom[r][c] != 0 else 0
                 for c in range(w)] for r in range(n)]
